func queueCurrentOutcomeState(q *QueueDetailModel) string {
	if q.TerminalOutcome != "" {
		return q.TerminalOutcome
	}
	// Never upgrade a projection-only success or failure to a disposition.
	switch q.CurrentState {
	case "queued", "claimed", "running", "cancelled", "denied", "expired", "revoked":
		return q.CurrentState
	}
	return ""
}

func queueOutcomeState(state string) string {
	switch state {
	case "queued", "claimed", "running", "succeeded", "failed", "denied", "cancelled", "expired", "revoked":
		return state
	default:
		return "unobserved"
	}
}

func queueOutcomeMessage(state string) string {
	switch state {
	case "succeeded":
		return "The authoritative Queue disposition records success. Selected content is a separate owner-authorized evidence read; native and Graph results are not selected-file output."
	case "failed":
		return "The authoritative Queue disposition records execution failure."
	case "denied":
		return "Execution was denied; no verified success is claimed."
	case "cancelled":
		return "Execution was cancelled; no verified success is claimed."
	case "expired":
		return "Execution expired; no verified success is claimed."
	case "revoked":
		return "Execution authority was revoked; no verified success is claimed."
	default:
		return "No authoritative terminal disposition is available. Process exit and interpreter terminal do not establish Queue success."
	}
}

// Closed public vocabulary: backend strings must never become a generic error banner.
func SafeQueueOutcomeReason(reason string) string {
	switch reason {
	case "implementation_failed", "implementation_verified", "verification_failed", "evidence_satisfied", "evidence_failed", "evidence_policy_missing", "evidence_verification_failed", "retry_exhausted", "cancelled", "expired", "revoked", "denied":
		return reason
	default:
		return "unavailable"
	}
}

